import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.CRkTBNIT.js";const m=JSON.parse('{"title":"Step 11: Gaps, Roadmap & Production Hardening","description":"","frontmatter":{},"headers":[],"relativePath":"10-gaps-and-improvements.md","filePath":"10-gaps-and-improvements.md"}'),i={name:"10-gaps-and-improvements.md"};function o(s,t,l,d,g,c){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="step-11-gaps-roadmap-production-hardening" tabindex="-1">Step 11: Gaps, Roadmap &amp; Production Hardening <a class="header-anchor" href="#step-11-gaps-roadmap-production-hardening" aria-label="Permalink to &quot;Step 11: Gaps, Roadmap &amp; Production Hardening&quot;">​</a></h1><p>This document outlines architectural trade-offs knowingly accepted in the current codebase and provides an engineering roadmap ranked by priority (P0, P1, P2) with concrete implementation suggestions.</p><hr><h2 id="priority-engineering-roadmap" tabindex="-1">Priority Engineering Roadmap <a class="header-anchor" href="#priority-engineering-roadmap" aria-label="Permalink to &quot;Priority Engineering Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Priority</th><th style="text-align:left;">Feature / Gap</th><th style="text-align:left;">Current State</th><th style="text-align:left;">Production Target &amp; Fix</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P0</strong></td><td style="text-align:left;"><strong>Distributed Message Backbone</strong></td><td style="text-align:left;">Database table queue (<code>queue_state</code>).</td><td style="text-align:left;">Replace relational queue state with <strong>Apache Kafka</strong> or <strong>AWS SQS FIFO</strong> for infinite horizontal queue scaling.</td></tr><tr><td style="text-align:left;"><strong>P0</strong></td><td style="text-align:left;"><strong>Distributed Rate Limiting</strong></td><td style="text-align:left;">Process-local token bucket (<code>TokenBucketRateLimiter</code>).</td><td style="text-align:left;">Migrate token bucket to <strong>Redis Cluster</strong> via Lua scripts (<code>EVALSHA</code>) to enforce shared rate limits across worker clusters.</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>Active Circuit Breaker</strong></td><td style="text-align:left;">Deterministic fallback sorting based on reported health.</td><td style="text-align:left;">Implement sliding-window circuit breakers (CLOSED, OPEN, HALF-OPEN) using Netflix Hystrix or Resilience4j algorithms.</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>Quiet-Hours Postponement Queue</strong></td><td style="text-align:left;">Suppressed messages terminate in <code>SUPPRESSED</code> status.</td><td style="text-align:left;">Add delayed queue release: hold suppressed notifications and automatically dispatch when local morning window opens (e.g. 08:01 AM).</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>Real-Time Console Push</strong></td><td style="text-align:left;">Operations console polls backend endpoints periodically.</td><td style="text-align:left;">Implement <strong>Server-Sent Events (SSE)</strong> or <strong>WebSockets</strong> for zero-latency live delivery feed updates.</td></tr><tr><td style="text-align:left;"><strong>P2</strong></td><td style="text-align:left;"><strong>Cold Storage Archival</strong></td><td style="text-align:left;">Delivery attempts remain in primary relational table.</td><td style="text-align:left;">Implement daily pg_partman partition rotation; archive records older than 90 days into ClickHouse or Amazon S3 Parquet.</td></tr><tr><td style="text-align:left;"><strong>P2</strong></td><td style="text-align:left;"><strong>Mutual TLS (mTLS)</strong></td><td style="text-align:left;">API key authentication in HTTP headers.</td><td style="text-align:left;">Enforce mTLS certificates for all inter-service communication within the service mesh.</td></tr></tbody></table>',5)])])}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
